import { CdkTrapFocus } from '@angular/cdk/a11y';
import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  effect,
  ElementRef,
  input,
  numberAttribute,
  OnDestroy,
  output,
  signal,
  TemplateRef,
  viewChild,
  ViewEncapsulation,
} from '@angular/core';

import {
  throwRichTooltipInvalidPositionX,
  throwRichTooltipInvalidPositionY,
} from './rich-tooltip-errors';
import {
  RichTooltipBehavior,
  RichTooltipCloseReason,
  RichTooltipPositionX,
  RichTooltipPositionY,
  RichTooltipRole,
  RichTooltipScrollStrategy,
} from './rich-tooltip-types';

/** Counter for generating unique element ids.
 * This is needed for accessibility.
 */
let idCounter = 0;

/**
 * The `SatRichTooltip` is used to display rich tooltips with various configurations.
 * It supports different positions, behaviors, and scroll strategies etc..
 */
@Component({
  selector: 'sat-rich-tooltip',
  templateUrl: './rich-tooltip.html',
  styleUrls: ['./rich-tooltip.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [CdkTrapFocus],
  exportAs: 'satRichTooltip',
})
export class SatRichTooltip implements OnDestroy {
  /** Closing disabled on richTooltip */
  closeDisabled = false;

  // TODO: DS-915
  /**
   * Unique id for the rich tooltip panel.
   * @deprecated in favor of automatic unique ID generation.
   */
  readonly id = input<string>();
  private readonly _id = `sat-rich-tooltip-${idCounter++}`;

  /**
   * Unique id for the visually hidden transient rich tooltip description element.
   * @internal
   */
  readonly descriptionId = `${this._id}-description`;

  /**
   * Unique id for the title element. Used as the `aria-labelledby` target on the
   * container in persistent mode.
   * @internal
   */
  readonly titleId = `${this._id}-title`;

  /**
   * Unique id for the content element. Used as the `aria-describedby` target on the
   * container in persistent mode.
   * @internal
   */
  readonly contentId = `${this._id}-content`;

  /**
   * Title text registered by `SatRichTooltipTitle` for the hidden description.
   * @internal
   */
  readonly titleDescription = signal('');

  /**
   * Content text registered by `SatRichTooltipContent` for the hidden description.
   * @internal
   */
  readonly contentDescription = signal('');

  /**
   * Plain-text description derived from projected title and content.
   * Used by the visually hidden element for screen reader announcement via aria-describedby.
   * @internal
   */
  readonly descriptionText = computed(() =>
    [this.titleDescription(), this.contentDescription()].join(' '),
  );

  // TODO: DS-915
  /**
   * aria-label for the rich tooltip panel.
   * @deprecated This input is deprecated in favor of a tailored message, and has no effect.
   */
  readonly ariaLabel = input<string | null>(null, { alias: 'aria-label' });

  // TODO: DS-915
  /**
   * aria-labelledby for the rich tooltip panel. This needs to be same with the id for the title element.
   * @deprecated This input is deprecated and has no effect.
   */
  readonly ariaLabelledby = input<string>('', { alias: 'aria-labelledby' });
  /**
   * aria-describedby for the rich tooltip panel. This needs to be same with the id for the content element.
   * @deprecated This input is deprecated and has no effect.
   */
  readonly ariaDescribedby = input<string>('', { alias: 'aria-describedby' });

  // TODO: DS-915
  /**
   * The ARIA role for the tooltip container.
   * @deprecated The role is now automatically determined by the `behavior` input.
   * Use `behavior="persistent"` for dialog role or `behavior="transient"` for tooltip role.
   * This input will be removed in a future version.
   */
  readonly role = input<RichTooltipRole | undefined>(undefined);

  private _roleWarningLogged = false;

  // TODO: DS-915 Rename to "role"
  /**
   * The resolved ARIA role for the tooltip container.
   * Derived from behavior: 'persistent' → 'dialog', 'transient' → 'tooltip'.
   * @internal
   */
  readonly resolvedRole = computed(() => (this.behavior() === 'persistent' ? 'dialog' : 'tooltip'));

  /**
   * Whether the tooltip has persistent behavior (interactive, click-triggered).
   * @internal
   */
  readonly isPersistent = computed(() => this.behavior() === 'persistent');

  /**
   * Position of the richTooltip in the X axis.
   * @default 'after'
   */
  readonly positionX = input<RichTooltipPositionX>('after');

  /**
   * Validated position of the richTooltip in the X axis.
   * Throws an error if the position is invalid.
   * @ignore
   */
  readonly validatedPositionX = computed(() => {
    const value = this.positionX();
    if (value !== 'before' && value !== 'after') {
      throwRichTooltipInvalidPositionX();
    }
    return value;
  });

  /**
   * Position of the richTooltip in the Y axis.
   * @default 'below'
   */
  readonly positionY = input<RichTooltipPositionY>('below');

  /**
   * Validated position of the richTooltip in the Y axis.
   * Throws an error if the position is invalid.
   * @ignore
   */
  readonly validatedPositionY = computed(() => {
    const value = this.positionY();
    if (value !== 'above' && value !== 'below') {
      throwRichTooltipInvalidPositionY();
    }
    return value;
  });

  /**
   * RichTooltip behavior type
   * @default 'transient'
   */
  readonly behavior = input<RichTooltipBehavior>('transient');

  /**
   * RichTooltip scroll strategy
   * @default 'reposition'
   */
  readonly scrollStrategy = input<RichTooltipScrollStrategy>('reposition');

  /**
   * RichTooltip enter delay (milliseconds)
   * @default 200
   */
  readonly showDelay = input<number, unknown>(200, { transform: numberAttribute });

  /**
   * RichTooltip leave delay (milliseconds)
   * @default 1500
   */
  readonly hideDelay = input<number, unknown>(1500, { transform: numberAttribute });

  /**
   * RichTooltip overlap trigger
   * @default false
   */
  readonly overlapTrigger = input(false, { transform: booleanAttribute });

  /**
   * RichTooltip horizontal target offset (px)
   * @default 0
   */
  readonly targetOffsetX = input<number, unknown>(0, { transform: numberAttribute });

  /**
   * RichTooltip vertical target offset (px)
   * @default 20
   */
  readonly targetOffsetY = input<number, unknown>(20, { transform: numberAttribute });

  // TODO: DS-915 Remove
  /**
   * @deprecated The `closeOnClick` input is deprecated and has no effect.
   * Use the `satRichTooltipClose` directive on action buttons to close the tooltip on click instead.
   */
  readonly closeOnClick = input(false, { transform: booleanAttribute });

  /**
   * Disable animations of richTooltip and all child elements
   * @default false
   */
  readonly disableAnimation = input(false, { transform: booleanAttribute });

  /**
   * Rich Tooltip focus trap using cdkTrapFocus
   * @default true
   */
  readonly focusTrapEnabled = input(true, { transform: booleanAttribute });

  /**
   * Rich Tooltip focus trap auto capture using cdkTrapFocusAutoCapture
   * @default true
   */
  readonly focusTrapAutoCaptureEnabled = input(true, { transform: booleanAttribute });

  /**
   * Event emitted when the richTooltip is closed.
   */
  readonly closed = output<RichTooltipCloseReason>();

  /**
   * Event emitted when the richTooltip is closed.
   *
   * @deprecated Switch to `closed` instead. Will be removed in future version.
   */
  // TODO: DS-915 Remove
  // eslint-disable-next-line @angular-eslint/no-output-native
  readonly close = output<RichTooltipCloseReason>();

  /** @ignore */
  readonly templateRef = viewChild<TemplateRef<ElementRef>>('richTooltipContainer');

  constructor() {
    // TODO: DS-915 Remove
    // Log deprecation warning if role input is used
    effect(() => {
      if (this.role() !== undefined && !this._roleWarningLogged) {
        this._roleWarningLogged = true;
        console.warn(
          'SatRichTooltip: The "role" input is deprecated and will be removed in a future version. ' +
            'The role is now automatically determined by the "behavior" input (persistent → dialog, transient → tooltip).',
        );
      }
    });
  }

  /**
   * Handle a keyboard event from the richTooltip, delegating to the appropriate action.
   * @internal
   */
  handleKeydown(event: KeyboardEvent) {
    if (event.key === 'Escape') {
      this.emitCloseEvent('keydown');
    }
  }

  /**
   * This emits a close event to which the trigger is subscribed. When emitted, the
   * trigger will close the richTooltip.
   * @internal
   */
  emitCloseEvent(reason: RichTooltipCloseReason): void {
    this.closed.emit(reason);
    // TODO: DS-915 Remove
    this.close.emit(reason);
  }

  /**
   * Prevents closing the Rich Tooltip when the user moves their pointer from the trigger element to the tooltip.
   * @internal
   */
  onMouseover() {
    if (this.behavior() === 'transient') {
      this.closeDisabled = true;
    }
  }

  /**
   * Enables closing of the Rich Tooltip when the user moves their pointer away from the Rich Tooltip element.
   * @internal
   */
  onMouseout() {
    if (this.behavior() === 'transient') {
      this.closeDisabled = false;
      this.emitCloseEvent('focusout');
    }
  }

  /** @ignore */
  doNothing() {
    //NOSONAR
    // Sonar incorrectly flags using mouseover and mouseleave without a focus event listener,
    // but in a transient Rich Tooltip, mouse events must prevent the Rich Tooltip from closing,
    // while focus events are non-existent since transient Rich Tooltips are not focusable.
  }

  ngOnDestroy(): void {
    this.emitCloseEvent();
  }
}
