import { Direction, Directionality } from '@angular/cdk/bidi';
import { Overlay, OverlayConfig, OverlayRef, ScrollStrategy } from '@angular/cdk/overlay';
import { inject, Injectable } from '@angular/core';

import { SatRichTooltip } from '../rich-tooltip';
import { RichTooltipScrollStrategy } from '../rich-tooltip-types';

/** @internal */
@Injectable()
export class RichTooltipOverlay {
  private readonly overlay = inject(Overlay);
  private readonly directionality = inject(Directionality);

  /** @ignore */
  // This method creates the overlay from the provided richTooltip's template and saves its OverlayRef so that it can be attached to the DOM when openRichTooltip is called.
  createOverlay(tooltip: SatRichTooltip): OverlayRef {
    return this.overlay.create(this.getOverlayConfig(tooltip));
  }

  /** @ignore */
  // The text direction of the containing app.
  get dir(): Direction {
    return this.directionality?.value === 'rtl' ? 'rtl' : 'ltr';
  }

  /** @ignore */
  // This method builds the configuration object needed to create the overlay, the OverlayConfig.
  getOverlayConfig(tooltip: SatRichTooltip): OverlayConfig {
    const overlayState = new OverlayConfig();

    /** Display overlay backdrop if trigger event is click */
    if (tooltip.behavior() === 'persistent') {
      overlayState.hasBackdrop = true;
      overlayState.backdropClass = 'cdk-overlay-transparent-backdrop';
    }

    overlayState.direction = this.dir;
    overlayState.scrollStrategy = this.getOverlayScrollStrategy(tooltip.scrollStrategy());

    return overlayState;
  }

  /** @ignore */
  // This method returns the scroll strategy used by the cdk/overlay.
  getOverlayScrollStrategy(strategy: RichTooltipScrollStrategy): ScrollStrategy {
    switch (strategy) {
      case 'noop':
        return this.overlay.scrollStrategies.noop();
      case 'close':
        return this.overlay.scrollStrategies.close();
      case 'block':
        return this.overlay.scrollStrategies.block();
      case 'reposition':
      default:
        return this.overlay.scrollStrategies.reposition();
    }
  }
}
