import {
  afterNextRender,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  inject,
  input,
  OnDestroy,
  ViewEncapsulation,
} from '@angular/core';

import { SatRichTooltip } from '../rich-tooltip';

/**
 * Component for rendering the title of the rich tooltip.
 */
@Component({
  selector: 'sat-rich-tooltip-title',
  template: `<ng-content></ng-content>`,
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: {
    'class': 'sat-rich-tooltip-title',
    'role': 'heading',
    'aria-level': '2',
    '[id]': 'id',
  },
})
export class SatRichTooltipTitle implements OnDestroy {
  private readonly elementRef = inject(ElementRef);
  private readonly tooltip = inject(SatRichTooltip);

  /** @internal */
  protected readonly id = this.tooltip.titleId;

  private _observer: MutationObserver | undefined;

  // TODO: DS-915 Remove
  /** @deprecated This element is not focusable and does not need an aria-label. */
  readonly ariaLabel = input<string>('', { alias: 'aria-label' });

  constructor() {
    afterNextRender(() => {
      const el: HTMLElement = this.elementRef.nativeElement;
      const update = () => this.tooltip.titleDescription.set(el.textContent?.trim() ?? '');

      update();

      this._observer = new MutationObserver(update);
      this._observer.observe(el, { subtree: true, characterData: true, childList: true });
    });
  }

  ngOnDestroy(): void {
    this._observer?.disconnect();
  }
}
